CREATE OR REPLACE FUNCTION public.siguiente_numero(p_tipo text, p_anio integer)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_num bigint;
begin
  insert into contador_documento (tipo, anio, ultimo_valor)
  values (p_tipo, p_anio, 1)
  on conflict (tipo, anio)
  do update set ultimo_valor = contador_documento.ultimo_valor + 1
  returning ultimo_valor into v_num;
  return v_num;
end;
$function$
CREATE OR REPLACE FUNCTION public.formato_numero(p_prefijo text, p_anio integer, p_valor bigint)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$ select p_prefijo || '-' || p_anio::text || '-' || lpad(p_valor::text, 5, '0') $function$
CREATE OR REPLACE FUNCTION public.app_es_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.perfil
    where id = auth.uid() and rol in ('admin','gerente') and activo
  );
$function$
CREATE OR REPLACE FUNCTION public.resumen_turno(p_sesion_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rol text;
  v_ses sesion_caja%rowtype;
  v_ventas jsonb; v_ventas_retail jsonb; v_ventas_vtd jsonb;
  v_anticipos jsonb; v_anulaciones jsonb; v_gastos jsonb;
  v_remesas numeric; v_inyecciones numeric; v_cantidad_ventas int; v_cantidad_vtd int;
  v_pendientes int; v_esperado numeric; v_neto numeric; v_rechazados jsonb;
  v_vtd_pend jsonb;
begin
  v_rol := app_rol_actual();
  if v_rol is null then raise exception 'No autorizado'; end if;

  select * into v_ses from sesion_caja where id = p_sesion_id;
  if not found then raise exception 'Sesión % no existe', p_sesion_id; end if;

  if v_rol = 'cajero' and v_ses.cajero_id is distinct from auth.uid() then
    raise exception 'Solo podés ver tu propio turno';
  elsif v_rol not in ('cajero', 'gerente', 'admin') then
    raise exception 'No autorizado';
  end if;

  select coalesce(jsonb_object_agg(metodo, monto), '{}'::jsonb) into v_ventas
    from (select metodo::text as metodo, sum(monto) as monto from movimiento_caja
           where sesion_caja_id = p_sesion_id and tipo = 'VENTA' group by metodo) t;

  select coalesce(jsonb_object_agg(metodo, monto), '{}'::jsonb) into v_ventas_retail
    from (select m.metodo::text as metodo, sum(m.monto) as monto
            from movimiento_caja m left join venta v on v.id = m.venta_id
           where m.sesion_caja_id = p_sesion_id and m.tipo = 'VENTA'
             and coalesce(v.numero, '') not like 'VTD-%'
           group by m.metodo) t;

  select coalesce(jsonb_object_agg(metodo, monto), '{}'::jsonb) into v_ventas_vtd
    from (select m.metodo::text as metodo, sum(m.monto) as monto
            from movimiento_caja m join venta v on v.id = m.venta_id
           where m.sesion_caja_id = p_sesion_id and m.tipo = 'VENTA'
             and v.numero like 'VTD-%'
           group by m.metodo) t;

  select coalesce(jsonb_object_agg(metodo, monto), '{}'::jsonb) into v_anticipos
    from (select metodo::text as metodo, sum(monto) as monto from movimiento_caja
           where sesion_caja_id = p_sesion_id and tipo = 'ANTICIPO' and not fuera_de_arqueo group by metodo) t;

  select coalesce(jsonb_object_agg(metodo, monto), '{}'::jsonb) into v_anulaciones
    from (select metodo::text as metodo, sum(monto) as monto from movimiento_caja
           where sesion_caja_id = p_sesion_id and tipo = 'ANULACION' group by metodo) t;

  select coalesce(jsonb_object_agg(lower(estado), monto), '{}'::jsonb) into v_gastos
    from (select g.estado, sum(g.monto) as monto from caja_gasto g
           where g.sesion_caja_id = p_sesion_id group by g.estado) t;

  select coalesce(sum(monto), 0) into v_remesas from movimiento_caja
   where sesion_caja_id = p_sesion_id and subtipo = 'REMESA';
  select coalesce(sum(monto), 0) into v_inyecciones from movimiento_caja
   where sesion_caja_id = p_sesion_id and subtipo = 'INYECCION';

  select count(*) into v_cantidad_ventas from venta
   where sesion_caja_id = p_sesion_id and estado = 'COMPLETADA'
     and coalesce(numero, '') not like 'VTD-%';

  select count(distinct m.venta_id) into v_cantidad_vtd
    from movimiento_caja m join venta v on v.id = m.venta_id
   where m.sesion_caja_id = p_sesion_id and m.tipo = 'VENTA' and v.numero like 'VTD-%';

  select jsonb_build_object('cantidad', count(*), 'total', coalesce(sum(total), 0))
    into v_vtd_pend
    from v_vtd_por_cobrar;

  select count(*) into v_pendientes from venta_pago vp
    join venta v on v.id = vp.venta_id
   where vp.estado_verificacion = 'PENDIENTE'
     and exists (select 1 from movimiento_caja m
                  where m.venta_id = v.id and m.sesion_caja_id = p_sesion_id and m.tipo = 'VENTA');

  select coalesce(jsonb_agg(jsonb_build_object('venta_id', v.id, 'numero', v.numero, 'metodo', vp.metodo, 'monto', vp.monto)), '[]'::jsonb)
    into v_rechazados
    from venta_pago vp join venta v on v.id = vp.venta_id
   where vp.estado_verificacion = 'RECHAZADO'
     and exists (select 1 from movimiento_caja m
                  where m.venta_id = v.id and m.sesion_caja_id = p_sesion_id and m.tipo = 'VENTA');

  if v_rol in ('gerente', 'admin') then
    select coalesce(sum(case when tipo in ('VENTA', 'ANTICIPO', 'INGRESO') then monto
                             when tipo in ('EGRESO', 'ANULACION') then -monto else 0 end), 0)
      into v_neto
    from movimiento_caja where sesion_caja_id = p_sesion_id and metodo = 'EFECTIVO' and not fuera_de_arqueo;
    v_esperado := v_ses.monto_apertura + v_neto;
  else
    v_esperado := null;
  end if;

  return jsonb_build_object(
    'apertura', v_ses.monto_apertura,
    'ventas', v_ventas,
    'ventas_retail', v_ventas_retail,
    'ventas_vtd', v_ventas_vtd,
    'anticipos', v_anticipos, 'cobros_fuera_arqueo', (select coalesce(sum(monto), 0) from movimiento_caja where sesion_caja_id = p_sesion_id and fuera_de_arqueo),
    'anulaciones', v_anulaciones,
    'gastos', v_gastos,
    'remesas', v_remesas,
    'inyecciones', v_inyecciones,
    'cantidad_ventas', v_cantidad_ventas,
    'cantidad_vtd_cobradas', v_cantidad_vtd,
    'vtd_por_cobrar', v_vtd_pend,
    'pagos_pendientes_verificacion', v_pendientes,
    'pagos_rechazados', v_rechazados,
    'diferencia_relevo', v_ses.diferencia_relevo,
    'esperado_efectivo', v_esperado
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.registrar_venta(p_lineas jsonb, p_pagos jsonb, p_sesion_caja_id bigint, p_cliente_id bigint DEFAULT NULL::bigint, p_descuento_total numeric DEFAULT 0, p_usuario text DEFAULT NULL::text, p_idempotencia text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
begin
  return _registrar_venta_nucleo(
    p_lineas, p_pagos, p_sesion_caja_id, p_cliente_id, p_descuento_total,
    p_usuario, p_idempotencia, false, null
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.anular_pedido(p_pedido_id bigint, p_motivo text, p_usuario text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_estado_actual pedido.estado%type;
  v_despachadas   int;
begin
  if p_motivo is null or btrim(p_motivo) = '' then
    raise exception 'El motivo es obligatorio';
  end if;

  select estado into v_estado_actual from pedido where id = p_pedido_id for update;
  if v_estado_actual is null then
    raise exception 'Pedido % no existe', p_pedido_id;
  end if;
  if v_estado_actual = 'CANCELADO' then
    raise exception 'El pedido ya está anulado';
  end if;

  select count(*) into v_despachadas
    from pedido_linea
   where pedido_id = p_pedido_id
     and estado in ('DESPACHADA', 'COMPRADO_DIRECTO');
  if v_despachadas > 0 then
    raise exception 'No se puede anular: tiene % línea(s) ya despachada(s)', v_despachadas;
  end if;

  update pedido set estado = 'CANCELADO' where id = p_pedido_id;

  insert into pedido_evento (pedido_id, accion, motivo, estado_previo, usuario)
  values (p_pedido_id, 'ANULADO', btrim(p_motivo), v_estado_actual, p_usuario);
end;
$function$
CREATE OR REPLACE FUNCTION public.anular_venta(p_venta_id bigint, p_usuario text DEFAULT NULL::text, p_sesion_caja_id bigint DEFAULT NULL::bigint, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_venta    venta%rowtype;
  v_k        record;
  v_p        record;
  v_rechazo  text;
  v_pagos    numeric;
  v_revert   int := 0;
begin
  select * into v_venta from venta where id = p_venta_id for update;
  if not found then
    raise exception 'Venta % no existe', p_venta_id;
  end if;

  if v_venta.estado not in ('COMPLETADA', 'ABIERTA') then
    raise exception 'La venta % está en estado % y no se puede anular',
      p_venta_id, v_venta.estado;
  end if;

  v_rechazo := app_puede_revertir_venta(p_venta_id, 'anular');
  if v_rechazo is not null then
    raise exception '%', v_rechazo using errcode = 'insufficient_privilege';
  end if;

  select coalesce(sum(monto), 0) into v_pagos
    from venta_pago where venta_id = p_venta_id;

  if v_pagos > 0 and p_sesion_caja_id is null then
    raise exception
      'La venta % tiene % cobrado: hay que indicar la sesión de caja donde se devuelve el dinero.',
      p_venta_id, v_pagos;
  end if;

  insert into venta_evento (venta_id, accion, motivo, usuario)
  values (p_venta_id, 'ANULADA', p_motivo, p_usuario);

  for v_k in
    select id, presentacion_id, ubicacion_id, cantidad
      from kardex_transacciones
     where referencia = 'Venta #' || p_venta_id and tipo_movimiento = 'SALIDA'
  loop
    perform registrar_entrada(v_k.presentacion_id, v_k.ubicacion_id, abs(v_k.cantidad),
                              'Anulación Venta #' || p_venta_id, p_usuario, current_date, null,
                              'anula:v' || p_venta_id || ':k' || v_k.id);
    v_revert := v_revert + 1;
  end loop;

  if p_sesion_caja_id is not null then
    perform 1 from sesion_caja where id = p_sesion_caja_id and estado = 'ABIERTA';
    if not found then
      raise exception 'La sesión de caja % no está abierta', p_sesion_caja_id;
    end if;
    for v_p in select metodo, monto from venta_pago where venta_id = p_venta_id loop
      insert into movimiento_caja (sesion_caja_id, tipo, metodo, monto, venta_id, creado_por, nota)
      values (p_sesion_caja_id, 'ANULACION', v_p.metodo, v_p.monto, p_venta_id, p_usuario,
              'Anulación de venta #' || p_venta_id);
    end loop;
  end if;

  update venta set estado = 'ANULADA' where id = p_venta_id;

  return jsonb_build_object(
    'venta_id',          p_venta_id,
    'estado',            'ANULADA',
    'estado_previo',     v_venta.estado,
    'kardex_revertido',  v_revert,
    'devuelto',          case when p_sesion_caja_id is not null then v_pagos else 0 end
  );
end;
$function$
